export function updateQuantity(cartId, delta) {
    const cartItem = cart.find(c => c.cartId === cartId);
    if (!cartItem) return;

    cartItem.quantity += delta;
    if (cartItem.quantity <= 0) {
        cart = cart.filter(c => c.cartId !== cartId);
    }
    notify();
}

